  1→"use client";
  2→
  3→import { useState } from "react";
  4→
  5→type PermissionEntry = {
  6→  resource: string;
  7→  action: string;
  8→  allowed: boolean;
  9→};
 10→
 11→type Props = {
 12→  roles: string[];
 13→  permissions: Record<string, PermissionEntry[]>;
 14→};
 15→
 16→const RESOURCE_GROUPS: { title: string; resources: { key: string; label: string }[] }[] = [
 17→  {
 18→    title: "대시보드",
 19→    resources: [
 20→      { key: "dashboard.summary", label: "현황 요약" },
 21→      { key: "dashboard.allocation", label: "TO 배분표" },
 22→      { key: "dashboard.progress", label: "채용 진행현황" },
 23→    ],
 24→  },
 25→  {
 26→    title: "후보자",
 27→    resources: [{ key: "candidates", label: "후보자 관리" }],
 28→  },
 29→  {
 30→    title: "채용 절차",
 31→    resources: [
 32→      { key: "procedures", label: "채용 절차 상세" },
 33→      { key: "actions", label: "단계별 제출" },
 34→    ],
 35→  },
 36→  {
 37→    title: "관리",
 38→    resources: [
 39→      { key: "admin.data-sheet", label: "데이터 관리 (DB 시트)" },
 40→      { key: "admin.workflow", label: "워크플로우 매트릭스" },
 41→    ],
 42→  },
 43→  {
 44→    title: "시스템",
 45→    resources: [
 46→      { key: "system.permissions", label: "권한 관리" },
 47→      { key: "system.users", label: "사용자 관리" },
 48→    ],
 49→  },
 50→  {
 51→    title: "기타",
 52→    resources: [{ key: "etc", label: "기타" }],
 53→  },
 54→];
 55→
 56→const ACTIONS = [
 57→  { key: "view", label: "보기" },
 58→  { key: "edit", label: "편집" },
 59→  { key: "delete", label: "삭제" },
 60→  { key: "export", label: "내보내기" },
 61→  { key: "import", label: "가져오기" },
 62→];
 63→
 64→export default function PermissionMatrix({ roles, permissions }: Props) {
 65→  const [activeRole, setActiveRole] = useState(roles[0] || "ADMIN");
 66→  const [localPerms, setLocalPerms] = useState(permissions);
 67→  const [saving, setSaving] = useState(false);
 68→  const [newRole, setNewRole] = useState("");
 69→  const [message, setMessage] = useState("");
 70→
 71→  function isAllowed(role: string, resource: string, action: string): boolean {
 72→    const perms = localPerms[role] || [];
 73→    const wildcard = perms.find((p) => p.resource === "*" && p.action === action);
 74→    if (wildcard) return wildcard.allowed;
 75→    const entry = perms.find((p) => p.resource === resource && p.action === action);
 76→    return entry?.allowed ?? false;
 77→  }
 78→
 79→  function toggle(resource: string, action: string) {
 80→    const current = isAllowed(activeRole, resource, action);
 81→    setLocalPerms((prev) => {
 82→      const rolePerms = [...(prev[activeRole] || [])];
 83→      const idx = rolePerms.findIndex(
 84→        (p) => p.resource === resource && p.action === action
 85→      );
 86→      if (idx >= 0) {
 87→        rolePerms[idx] = { ...rolePerms[idx], allowed: !current };
 88→      } else {
 89→        rolePerms.push({ resource, action, allowed: !current });
 90→      }
 91→      return { ...prev, [activeRole]: rolePerms };
 92→    });
 93→  }
 94→
 95→  async function save() {
 96→    setSaving(true);
 97→    setMessage("");
 98→    const original = permissions[activeRole] || [];
 99→    const current = localPerms[activeRole] || [];
100→    const changes: { resource: string; action: string; allowed: boolean }[] = [];
101→
102→    for (const c of current) {
103→      const orig = original.find(
104→        (o) => o.resource === c.resource && o.action === c.action
105→      );
106→      if (!orig || orig.allowed !== c.allowed) {
107→        changes.push(c);
108→      }
109→    }
110→
111→    if (changes.length > 0) {
112→      await fetch("/api/permissions", {
113→        method: "PATCH",
114→        headers: { "Content-Type": "application/json" },
115→        body: JSON.stringify({ role: activeRole, changes }),
116→      });
117→      setMessage("권한이 저장되었습니다.");
118→    } else {
119→      setMessage("변경사항이 없습니다.");
120→    }
121→    setSaving(false);
122→  }
123→
124→  async function addRole() {
125→    if (!newRole.trim()) return;
126→    await fetch("/api/roles", {
127→      method: "POST",
128→      headers: { "Content-Type": "application/json" },
129→      body: JSON.stringify({ role: newRole.trim() }),
130→    });
131→    window.location.reload();
132→  }
133→
134→  // 역할 탭 순서: ADMIN → DEAN → VIP → 나머지
135→  const sortedRoles = [...roles].sort((a, b) => {
136→    const order: Record<string, number> = { ADMIN: 0, DEAN: 1, VIP: 2 };
137→    return (order[a] ?? 3) - (order[b] ?? 3);
138→  });
139→
140→  return (
141→    <div>
142→      {/* Header */}
143→      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20, flexWrap: "wrap", gap: 12 }}>
144→        <div>
145→          <h2 style={{ fontSize: 18, fontWeight: 600, color: "var(--text-title)", margin: 0 }}>
146→            권한 관리
147→          </h2>
148→          <p style={{ fontSize: 12, color: "var(--text-secondary)", margin: "2px 0 0" }}>
149→            역할별 페이지 및 기능 접근 권한을 설정합니다
150→          </p>
151→        </div>
152→        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
153→          <div style={{ display: "flex", gap: 4 }}>
154→            <input
155→              value={newRole}
156→              onChange={(e) => setNewRole(e.target.value)}
157→              placeholder="새 역할명"
158→              className="input"
159→              style={{ width: 120 }}
160→            />
161→            <button className="btn-secondary" onClick={addRole}>
162→              + 추가
163→            </button>
164→          </div>
165→          <button className="btn-primary" onClick={save} disabled={saving}>
166→            {saving ? "저장 중..." : "변경사항 저장"}
167→          </button>
168→        </div>
169→      </div>
170→
171→      {/* Role tabs */}
172→      <div style={{ display: "flex", gap: 4, marginBottom: 20 }}>
173→        {sortedRoles.map((role) => (
174→          <button
175→            key={role}
176→            onClick={() => setActiveRole(role)}
177→            style={{
178→              padding: "8px 16px",
179→              background: role === activeRole ? "var(--deep-green)" : "var(--card-bg)",
180→              color: role === activeRole ? "#fff" : "var(--text-body)",
181→              border: role === activeRole ? "none" : "1px solid var(--divider)",
182→              borderRadius: 6,
183→              fontSize: 12,
184→              fontWeight: role === activeRole ? 500 : 400,
185→              cursor: "pointer",
186→            }}
187→          >
188→            {role}
189→          </button>
190→        ))}
191→      </div>
192→
193→      {/* Matrix table */}
194→      <div className="card" style={{ padding: 0, overflow: "hidden" }}>
195→        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
196→          <thead>
197→            <tr style={{ background: "var(--header-bg)" }}>
198→              <th style={{ textAlign: "left", padding: "10px 14px", color: "var(--text-secondary)", fontWeight: 500, fontSize: 11, width: "30%" }}>
199→                리소스
200→              </th>
201→              {ACTIONS.map((a) => (
202→                <th key={a.key} style={{ textAlign: "center", padding: "10px 14px", color: "var(--text-secondary)", fontWeight: 500, fontSize: 11, width: "14%" }}>
203→                  {a.label}
204→                </th>
205→              ))}
206→            </tr>
207→          </thead>
208→          <tbody>
209→            {RESOURCE_GROUPS.map((group) => (
210→              <tbody key={group.title}>
211→                <tr style={{ background: "var(--header-bg)" }}>
212→                  <td
213→                    colSpan={6}
214→                    style={{
215→                      padding: "8px 14px",
216→                      fontSize: 10,
217→                      color: "var(--text-secondary)",
218→                      fontWeight: 600,
219→                      textTransform: "uppercase",
220→                      letterSpacing: 0.5,
221→                    }}
222→                  >
223→                    {group.title}
224→                  </td>
225→                </tr>
226→                {group.resources.map((res) => (
227→                  <tr key={res.key} style={{ borderTop: "1px solid var(--divider)" }}>
228→                    <td style={{ padding: "10px 14px", color: "var(--text-body)" }}>
229→                      {res.label}
230→                    </td>
231→                    {ACTIONS.map((action) => {
232→                      const allowed = isAllowed(activeRole, res.key, action.key);
233→                      return (
234→                        <td key={action.key} style={{ textAlign: "center", padding: "10px 14px" }}>
235→                          <div
236→                            onClick={() => toggle(res.key, action.key)}
237→                            style={{
238→                              width: 18,
239→                              height: 18,
240→                              background: allowed ? "var(--primary-green)" : "#e0e0e0",
241→                              borderRadius: 4,
242→                              margin: "0 auto",
243→                              display: "flex",
244→                              alignItems: "center",
245→                              justifyContent: "center",
246→                              cursor: "pointer",
247→                            }}
248→                          >
249→                            {allowed && (
250→                              <span style={{ color: "#fff", fontSize: 11 }}>&#10003;</span>
251→                            )}
252→                          </div>
253→                        </td>
254→                      );
255→                    })}
256→                  </tr>
257→                ))}
258→              </tbody>
259→            ))}
260→          </tbody>
261→        </table>
262→      </div>
263→
264→      {/* Legend + message */}
265→      <div style={{ display: "flex", gap: 16, marginTop: 12, fontSize: 11, color: "var(--text-secondary)", alignItems: "center", flexWrap: "wrap" }}>
266→        <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
267→          <div style={{ width: 14, height: 14, background: "var(--primary-green)", borderRadius: 3, display: "flex", alignItems: "center", justifyContent: "center" }}>
268→            <span style={{ color: "#fff", fontSize: 9 }}>&#10003;</span>
269→          </div>
270→          허용
271→        </div>
272→        <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
273→          <div style={{ width: 14, height: 14, background: "#e0e0e0", borderRadius: 3 }} />
274→          차단
275→        </div>
276→        <span style={{ color: "var(--text-disabled)" }}>|</span>
277→        <span>클릭하여 토글</span>
278→        {message && (
279→          <span style={{ marginLeft: "auto", color: "var(--primary-green)", fontWeight: 500 }}>
280→            {message}
281→          </span>
282→        )}
283→      </div>
284→    </div>
285→  );
286→}
